async function captureOnboardingBrandEvidence(){const onboarding=await launch('brand-onboarding');await onboarding.page.waitForFunction(()=>document.getElementById('ob-root').classList.contains('active'));for(const theme of ['light','dark']){await onboarding.page.setViewportSize({width:390,height:844});await onboarding.page.evaluate(theme=>{S.settings.theme=theme;applyTheme();obRender();},theme);await onboarding.page.waitForFunction(theme=>document.documentElement.getAttribute('data-theme')===theme,theme);const logos=await visibleBrandLogo(onboarding.page,'.onboarding-brand-lockup');equal(logos.filter(item=>item.visible).length,1,`onboarding ${theme}: exactly one Brand Logo is visible`);equal(logos.find(item=>item.visible).src,`/assets/brand/derived/taxmate-brand-logo-${theme}.svg`,`onboarding ${theme}: correct Brand Logo renders`);equal(await onboarding.page.locator('.lo-mark,.lo-name').count(),0,`onboarding ${theme}: old pound mark and duplicate TaxMate text are absent`);const name=`brand-onboarding-${theme}.png`;await onboarding.page.screenshot({path:path.join(evidence,name),fullPage:true});brandEvidence.push({name,screen:'onboarding-login',theme,viewport:{width:390,height:844},logos});}await onboarding.context.close();}
async function captureStep1Evidence(page){const captures=[['actual-app-step1-mobile-light-en.png','en','light',{width:390,height:844}],['actual-app-step1-mobile-dark-en.png','en','dark',{width:390,height:844}],['actual-app-step1-desktop-light-en.png','en','light',{width:1440,height:1000}],['actual-app-step1-desktop-dark-en.png','en','dark',{width:1440,height:1000}],['actual-app-step1-mobile-light-ur-rtl.png','ur','light',{width:390,height:844}]];for(const [name,locale,theme,viewport] of captures){await setLtdPresentation(page,locale,theme,viewport);await assertLtdShell(page,`Step 1 ${locale} ${theme} ${viewport.width}`);equal(await page.locator('[data-field="companyNumber"]').inputValue(),'11111111',`${name}: checked company number survives locale/theme/viewport repaint`);equal(await page.locator('[data-field="legalName"]').inputValue(),'TOODALOOP LTD',`${name}: official company name autofill survives locale/theme/viewport repaint`);equal(await page.locator('[data-field="incorporationDate"]').inputValue(),'15/12/2025',`${name}: official incorporation date autofill survives locale/theme/viewport repaint`);const lookupText=await page.locator('.tm-company-identity-stack .tm-notice').allTextContents();check(lookupText.some(text=>text.includes('TOODALOOP LTD'))&&lookupText.some(text=>text.includes('15/12/2025')),`${name}: lookup result card renders official name and date`);const stack=page.locator('.tm-company-identity-stack');equal(await stack.count(),1,`${name}: identity fields share one grouped container`);const boxes=await stack.locator(':scope > .tm-field').evaluateAll(nodes=>nodes.map(node=>{const rect=node.getBoundingClientRect();return{top:rect.top,bottom:rect.bottom,width:rect.width};}));check(boxes.length===3&&boxes.every(item=>item.width>0),`${name}: all three identity fields are visibly grouped`);check(boxes.slice(1).every((item,index)=>item.top-boxes[index].bottom>=14),`${name}: grouped identity fields keep a visible consistent gap`);await page.screenshot({path:path.join(evidence,name),fullPage:true});visualEvidence.push({name,screen:'ltd.onboarding.step1',locale,theme,viewport,identityFieldBoxes:boxes,autofill:{companyNumber:'11111111',legalName:'TOODALOOP LTD',incorporationDate:'15/12/2025',source:'real Check Companies House button'}});}await setLtdPresentation(page,'en','light',{width:390,height:844});}
async function seedLtdCloud(uid,state){const companyIds=new Set(state.domain.entities.filter(item=>item.type==='limited_company'&&item.deletedAt==null).map(item=>item.id)),records=LtdSync.recordsForSync(state);for(const collection of LtdSync.COLLECTIONS)for(const record of records[collection]){const envelope=LtdSync.envelope(collection,record,LtdSync.companyIdForRecord(collection,record,companyIds));await adminSet(`users/${uid}/ltd/v1/${collection}/${envelope.documentId}`,envelope);}const companyId=state.domain.companyProfiles.find(item=>item.deletedAt==null).entityId;await adminSet(`users/${uid}/ltdControl/activeCompany`,{schemaVersion:1,status:'active_slot_claimed',activeCompanyId:companyId,releasePolicy:'founder_approval_required',claimedAt:Date.now(),updatedAt:Date.now()});}

async function lookupThroughRealBlurClick(page,number,expectedStatus){
  const companyNumber=page.locator('[data-field="companyNumber"]'),checkButton=page.getByRole('button',{name:'Check Companies House',exact:true});
  await companyNumber.fill(number);
  await page.evaluate(()=>{window.__blurClickTrace=[];const input=document.querySelector('[data-field="companyNumber"]'),button=[...document.querySelectorAll('button')].find(node=>node.textContent.trim()==='Check Companies House');input.addEventListener('blur',()=>window.__blurClickTrace.push('blur'));button.addEventListener('click',()=>window.__blurClickTrace.push('click'));});
  const before=await page.evaluate(()=>window.__companiesHouseCalls.length);
  await companyNumber.focus();await checkButton.click();
  await waitFor(()=>page.evaluate(status=>TaxMateLtdUIFacade.getSnapshot().lookupStatus.status===status,expectedStatus),`real blur-to-click lookup did not reach ${expectedStatus}`);
  equal(await page.evaluate(()=>window.__blurClickTrace),['blur','click'],`${expectedStatus}: input blur preserves the exact button through click dispatch`);
  equal(await page.evaluate(()=>window.__companiesHouseCalls.length),before+1,`${expectedStatus}: real UI click invokes Companies House exactly once`);
  return page.evaluate(()=>({calls:window.__companiesHouseCalls.slice(),lookup:TaxMateLtdUIFacade.getSnapshot().lookupStatus,number:document.querySelector('[data-field="companyNumber"]')&&document.querySelector('[data-field="companyNumber"]').value,busy:TaxMateLtdUIFacade.getSnapshot().busy,route:TaxMateLtdUIFacade.getSnapshot().navigation.routes.at(-1).screenId,trace:window.__blurClickTrace.slice()}));
}

